import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **The folder question ("trust this folder?") against the daemon's own bytes.**
///
/// `folder-trust-wire.json` is what ccd emits (`fixtures/wire/folder-trust-wire.json`, regenerated by ccd's test and
/// copied here byte for byte): a start without an answer and the `needs_trust` it gets, the start that answers, and
/// the three folder-trust frames with the `folder_trust` list they get.
@MainActor
final class FolderTrustWireTests: XCTestCase {

    // MARK: Harness

    private static let folder = "/tmp/ccd-folder-trust/my app"

    private func wire() throws -> [String: JSONValue] {
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "folder-trust-wire", withExtension: "json"))
        return try XCTUnwrap(try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func frame(_ key: String) throws -> ServerMessage {
        let value = try XCTUnwrap(try wire()[key], "no \(key) in folder-trust-wire.json")
        return try JSONDecoder().decode(ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
    }

    private func encoded(_ message: ClientMessage) throws -> JSONValue {
        try JSONDecoder().decode(JSONValue.self, from: JSONEncoder().encode(message))
    }

    private final class Sent {
        var sent: [ClientMessage] = []

        /// Each start sent, by request id, with the answer it carried.
        var starts: [(requestID: String, trust: FolderTrust?)] {
            sent.compactMap {
                guard case .startSession(let id, _, _, _, _, _, let trust) = $0 else { return nil }
                return (id, trust)
            }
        }
    }

    private func model() throws -> (AppModel, Sent) {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("folder-trust-\(UUID().uuidString)")
        addTeardownBlock { try? FileManager.default.removeItem(at: root) }
        let model = AppModel(
            cache: EventCache(root: root),
            codexSpentLedger: CodexSpentLedger(defaults: UserDefaults(suiteName: "cc.tests.\(UUID().uuidString)")!))
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "minor-30-wire", withExtension: "json"))
        let minor30 = try XCTUnwrap(try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
        let advertised = try XCTUnwrap(minor30["hello_ack_capabilities"])
        model.connection.simulateConnectedForTesting()
        model.connection.simulateCapabilitiesForTesting(
            try JSONDecoder().decode(Capabilities.self, from: Data(advertised.canonicalJSONString.utf8)), minor: 30)
        let sent = Sent()
        model.connection.sendStub = { message in MainActor.assumeIsolated { sent.sent.append(message) } }
        addTeardownBlock { @MainActor in model.scenePhaseChanged(to: .background) }
        return (model, sent)
    }

    /// A give-a-chance settle, for a negative check (assert something was NOT sent).
    private func settle() async {
        for _ in 0..<5 { await Task.yield() }
    }

    /// Polls `condition` on the main actor, sleeping briefly between checks, until it
    /// holds or a generous bound elapses — so a send that takes an unknown number of
    /// turns under load is waited for, not guessed at with a fixed yield count.
    private func waitUntil(
        _ condition: () -> Bool, _ what: String,
        file: StaticString = #filePath, line: UInt = #line
    ) async {
        for _ in 0..<1000 {
            if condition() { return }
            try? await Task.sleep(nanoseconds: 2_000_000)
        }
        XCTFail("timed out waiting for \(what)", file: file, line: line)
    }

    private var project: StartProject {
        StartProject(path: Self.folder, name: "my app", lastUsed: Date(), lastAgent: nil, gitBranch: nil, exists: true)
    }

    /// A second `hello_ack`, as after a reconnect: the handshake that sends unanswered starts again.
    private func reconnect(_ model: AppModel) throws {
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "minor-30-wire", withExtension: "json"))
        let minor30 = try XCTUnwrap(try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
        let hello = """
            {"type":"hello_ack","protocol_version":\(Wire.protocolVersion),"protocol_minor":30,\
            "server_time":"2026-11-12T20:00:00.000Z","capabilities":\(try XCTUnwrap(minor30["hello_ack_capabilities"]).canonicalJSONString)}
            """
        model.connection.injectForTesting(try JSONDecoder().decode(ServerMessage.self, from: Data(hello.utf8)))
    }

    // MARK: The wire

    func testTheQuestionDecodesWithTheFoldersRealPath() throws {
        guard case .startSessionResult(let id, let outcome) = try frame("start_session_needs_trust") else {
            return XCTFail("not a start_session_result")
        }
        XCTAssertEqual(id, "r1")
        XCTAssertEqual(outcome, .needsTrust(path: Self.folder))
    }

    func testTheAnswersDecodeAsKept() throws {
        guard case .folderTrust(let id, let folders) = try frame("folder_trust") else {
            return XCTFail("not a folder_trust frame")
        }
        XCTAssertEqual(id, "t1")
        let answeredAt = try XCTUnwrap(ISO8601.parse("2026-11-12T20:00:00Z"))
        XCTAssertEqual(folders, [FolderAnswer(path: Self.folder, trust: .notTrusted, answeredAt: answeredAt)])
    }

    func testTheFolderFramesAreSentAsTheDaemonReadsThem() throws {
        let wire = try wire()
        XCTAssertEqual(try encoded(.listFolderTrust(requestID: "t1")), wire["list_folder_trust_request"])
        XCTAssertEqual(
            try encoded(.setFolderTrust(requestID: "t2", path: Self.folder, trust: .trusted)),
            wire["set_folder_trust_request"])
        XCTAssertEqual(
            try encoded(.forgetFolderTrust(requestID: "t3", path: Self.folder)), wire["forget_folder_trust_request"])
    }

    /// A start without an answer, and the start that answers, are the daemon's own `start_session`s.
    func testBothStartsAreSentAsTheDaemonReadsThem() async throws {
        let wire = try wire()
        let (model, sent) = try model()
        let context = StartContext(model: model)
        let asking = context.start(project, agent: .claude, prompt: "fix the tests")
        let answering = context.start(project, agent: .claude, prompt: "fix the tests", trust: .notTrusted)
        await waitUntil({ sent.sent.count >= 2 }, "both starts to be sent")
        let byID = Dictionary(
            uniqueKeysWithValues: try sent.sent.map { message -> (String, JSONValue) in
                let object = try XCTUnwrap(try encoded(message).objectValue)
                return (try XCTUnwrap(object["request_id"]?.stringValue), .object(object))
            })
        var first = try XCTUnwrap(byID[asking]?.objectValue)
        first["request_id"] = .string("r1")
        XCTAssertEqual(.object(first), wire["start_session_request"])
        var second = try XCTUnwrap(byID[answering]?.objectValue)
        second["request_id"] = .string("r2")
        XCTAssertEqual(.object(second), wire["start_session_answered_request"])
    }

    /// A start that carries an answer carries it again when a reconnect sends it again, under the same id.
    func testAnAnswerIsSentAgainWithItsStart() async throws {
        let (model, sent) = try model()
        let id = model.startSession(project, agent: .claude, prompt: "fix the tests", trust: .notTrusted)
        await waitUntil({ sent.starts.contains { $0.requestID == id } }, "the start to be sent")
        try reconnect(model)
        await waitUntil({ sent.starts.filter { $0.requestID == id }.count >= 2 }, "the start re-sent on reconnect")
        let starts = sent.starts.filter { $0.requestID == id }
        XCTAssertEqual(starts.count, 2, "sent, then sent again")
        XCTAssertEqual(starts.map(\.trust), [.notTrusted, .notTrusted])
    }

    /// The question is the start's answer: it is kept, and the start is not sent again.
    func testTheQuestionSettlesItsStart() async throws {
        let (model, sent) = try model()
        let id = model.startSession(project, agent: .claude, prompt: "fix the tests")
        await waitUntil({ sent.starts.contains { $0.requestID == id } }, "the start to be sent")
        model.connection.injectForTesting(.startSessionResult(requestID: id, outcome: .needsTrust(path: Self.folder)))
        XCTAssertEqual(model.starter.starts[id]?.outcome, .needsTrust(path: Self.folder))
        try reconnect(model)
        await settle()
        XCTAssertEqual(sent.starts.filter { $0.requestID == id }.count, 1, "an answered start is not sent again")
    }

    /// Each of the connection's three asks gets the `folder_trust` answering its own request id.
    func testEachAskGetsTheListAnsweringIt() async throws {
        let (model, sent) = try model()
        let answer = FolderAnswer(path: Self.folder, trust: .trusted, answeredAt: Date(timeIntervalSince1970: 0))
        func answered(_ ask: @escaping () async throws -> [FolderAnswer]) async throws -> [FolderAnswer] {
            let before = sent.sent.count
            async let folders = ask()
            await waitUntil({ sent.sent.count > before }, "the ask's frame to be sent")
            let id: String? =
                switch sent.sent[before] {
                case .listFolderTrust(let id), .setFolderTrust(let id, _, _), .forgetFolderTrust(let id, _): id
                default: nil
                }
            model.connection.injectForTesting(.folderTrust(requestID: try XCTUnwrap(id), folders: [answer]))
            return try await folders
        }
        let connection = model.connection
        let listed = try await answered { try await connection.listFolderTrust() }
        XCTAssertEqual(listed, [answer])
        let set = try await answered { try await connection.setFolderTrust(path: Self.folder, trust: .trusted) }
        XCTAssertEqual(set, [answer])
        guard case .setFolderTrust(_, let path, let trust) = sent.sent.last else { return XCTFail("no set sent") }
        XCTAssertEqual(path, Self.folder)
        XCTAssertEqual(trust, .trusted)
        let forgotten = try await answered { try await connection.forgetFolderTrust(path: Self.folder) }
        XCTAssertEqual(forgotten, [answer])
        guard case .forgetFolderTrust(_, let gone) = sent.sent.last else { return XCTFail("no forget sent") }
        XCTAssertEqual(gone, Self.folder)
    }
}
